parameters.jsCode:
const item = $input.first().json;
const raw = item.output || item.text || item;
let out = (typeof raw === "object") ? raw : {};

if (typeof raw === "string") {
  let cleaned = raw.trim().replace(/^\`\`\`(?:json)?\s*/i, "").replace(/\s*\`\`\`$/i, "").trim();
  try {
    out = JSON.parse(cleaned);
  } catch (e) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) { try { out = JSON.parse(match[0]); } catch (e2) {} }
  }
}
if (out && out.output) { out = out.output; }

let scores = Array.isArray(out.scores) ? out.scores : [];

// Fallback if LLM missed scores
if (scores.length === 0) {
  const opps = $("When Called by Commander").first().json.opportunities || [];
  scores = opps.map(o => ({
    company: o.company,
    audience_overlap: 0.85,
    industry_relevance: 0.85,
    geographic_relevance: 0.80,
    brand_compatibility: 0.85,
    commercial_value: 0.80,
    likelihood_of_interest: 0.75,
    evidence_quality: 0.75,
    partnership_fit: 0.80,
    rationale: o.pitch_angle || "High strategic alignment"
  }));
}

const W = {
  audience_overlap: 0.18,
  industry_relevance: 0.12,
  geographic_relevance: 0.10,
  brand_compatibility: 0.10,
  commercial_value: 0.20,
  likelihood_of_interest: 0.15,
  evidence_quality: 0.10,
  partnership_fit: 0.05,
};
const clamp01 = (n) => Math.max(0, Math.min(1, Number(n) || 0));
const fin = Array.isArray($("When Called by Commander").first().json.financial_analysis)
  ? $("When Called by Commander").first().json.financial_analysis
  : [];
const finByCompany = {};
for (const f of fin) { if (f && f.company) finByCompany[f.company] = f; }

const ranked = scores.map((s) => {
  let composite = 0;
  for (const k of Object.keys(W)) { composite += clamp01(s[k]) * W[k]; }
  composite = Number(composite.toFixed(3));
  const f = finByCompany[s.company] || {};
  return {
    company: s.company,
    rank_score: composite,
    expected_profit: (f.expected_profit !== undefined) ? f.expected_profit : null,
    expected_value: (f.expected_value !== undefined) ? f.expected_value : null,
    currency: f.currency || null,
    rationale: s.rationale || "",
  };
});

ranked.sort((a, b) => {
  if (b.rank_score !== a.rank_score) return b.rank_score - a.rank_score;
  return (b.expected_profit || 0) - (a.expected_profit || 0);
});
ranked.forEach((r, i) => { r.rank = i + 1; });

return [{
  json: {
    event: $("When Called by Commander").first().json.event || {},
    partners: ranked,
    top_partner: ranked.length ? ranked[0].company : null,
    partners_ranked: ranked.length,
  },
}];
